import type { ApiClientType, ClientTypeMap } from './ClientRegistry';
import type { AuthenticatedMethods } from './authenticatedMethods.generated';

/**
 * A custom domain client with every method that needs a token left out, and
 * the views and generic page helpers that could reach one. The method list
 * is generated by running each method on a client that holds no token
 * (`npm run generate:public-clients`), so a new authenticated method drops
 * out when the file is regenerated, and a stale file fails the unit suite.
 *
 * `EsiClientBuilder.buildPublic()` hands these out. See guides/USAGE.md.
 */
export type PublicClient<K extends ApiClientType> = Omit<
  ClientTypeMap[K],
  | AuthenticatedMethods[K]
  | 'withMetadata'
  | 'withSafeMode'
  | 'streamEndpoint'
  | 'fetchAllEndpoint'
>;

/** The domain accessors of a public-only custom client; undefined for a domain it was not built with. */
export type PublicDomainClients = {
  readonly [K in ApiClientType]: PublicClient<K> | undefined;
};
